[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Destination)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Destination);if(Test-Path $d){throw 'PORTABLE_TARGET_EXISTS'};New-Item -ItemType Directory -Force (Join-Path $d 'pages')|Out-Null
$pages=@();1..19|%{$id="PAGE-PORT-$('{0:D2}' -f $_)";$parent=if($_ -eq 1){$null}else{'PAGE-PORT-01'};Set-Content (Join-Path $d "pages/$id.md") "---`nid: $id`nparent: $parent`nversion: 1`nstatus: published`n---`n# Synthetic page" -Encoding utf8;$pages+=[ordered]@{id=$id;parent=$parent;version=1;status='published';sourcePath="pages/$id.md"}}
$e=[ordered]@{id='EVID-PORT-01';hash=('a'*64);type='synthetic'};$tickets=@();1..17|%{$id="TKT-PORT-$('{0:D2}' -f $_)";$h=if($_ -le 16){4}else{16};$tickets+=[ordered]@{id=$id;type='task';summary=$id;reporter='synthetic';assignee='synthetic';status='closed';priority='P3';created='2026-02-01T09:00:00Z';status_history=@([ordered]@{status='open';time='2026-02-01T09:00:00Z'},[ordered]@{status='closed';time='2026-02-03T09:00:00Z'});acceptance=@('pass');evidence=@('EVID-PORT-01');comments=@([ordered]@{id="COM-$id-1";type='working';author_role='synthetic';text='work';time='2026-02-02T09:00:00Z';evidence=@()},[ordered]@{id="COM-$id-2";type='closing';author_role='synthetic';text='closed';time='2026-02-03T09:00:00Z';evidence=@('EVID-PORT-01')});worklogs=@([ordered]@{id="WL-$id";hours=$h;cost=($h*120);date='2026-02-02'})}}
$events=@();1..15|%{$events+=[ordered]@{id="EV-PORT-$('{0:D2}' -f $_)";time="2026-02-$('{0:D2}' -f (($_%20)+1))T10:00:00Z";phase='implementation';references=@('PAGE-PORT-01','TKT-PORT-01','EVID-PORT-01','SESSION-PORT-01','DECISION-PORT-01','DELIVERABLE-PORT-01');nextStep='continue'}}
$edges=@([ordered]@{from='PAGE-PORT-01';to='TKT-PORT-01';type='page-ticket'},[ordered]@{from='TKT-PORT-01';to='PAGE-PORT-01';type='ticket-page'});$story=[ordered]@{project_id='PROJECT-PORTABLE';story_id='STORY-PORTABLE';classification='synthetic';status='hypercare';offer=[ordered]@{versions=@([ordered]@{version=1},[ordered]@{version=2},[ordered]@{version=3});start_time='2026-02-01T00:00:00Z';end_time='2026-02-20T23:59:59Z';planned_hours=100;actual_hours=80;planned_cost=12000;actual_cost=9600};pages=$pages;tickets=$tickets;timeline=$events;hypercare=@(1,2,3|%{[ordered]@{day=$_;status='closed';daily_page='PAGE-PORT-01';tickets=@('TKT-PORT-01');diagnosis='synthetic';fix='synthetic';retest='pass';go_no_go='GO'}});evidence=@($e);sessions=@([ordered]@{id='SESSION-PORT-01'});decisions=@([ordered]@{id='DECISION-PORT-01'});deliverables=@([ordered]@{id='DELIVERABLE-PORT-01'});graph=$edges};$story|ConvertTo-Json -Depth 40|Set-Content (Join-Path $d 'project-story.json') -Encoding utf8;Write-Host 'PASS: Portable conformance fixture generated.'
 $out=Get-Content (Join-Path $d 'project-story.json') -Raw|ConvertFrom-Json;$out.hypercare|%{Add-Member -InputObject $_ -NotePropertyName comment -NotePropertyValue 'COM-TKT-PORT-01-2' -Force;Add-Member -InputObject $_ -NotePropertyName evidence -NotePropertyValue @('EVID-PORT-01') -Force};$out.graph=@([ordered]@{from='PAGE-PORT-01';to='TKT-PORT-01';type='page-ticket'},[ordered]@{from='TKT-PORT-01';to='PAGE-PORT-01';type='ticket-page'},[ordered]@{from='TKT-PORT-01';to='EVID-PORT-01';type='ticket-evidence'},[ordered]@{from='EVID-PORT-01';to='TKT-PORT-01';type='evidence-ticket'},[ordered]@{from='PAGE-PORT-01';to='SESSION-PORT-01';type='page-session'},[ordered]@{from='SESSION-PORT-01';to='PAGE-PORT-01';type='session-page'},[ordered]@{from='TKT-PORT-01';to='DECISION-PORT-01';type='ticket-decision'},[ordered]@{from='DECISION-PORT-01';to='TKT-PORT-01';type='decision-ticket'},[ordered]@{from='TKT-PORT-01';to='DELIVERABLE-PORT-01';type='ticket-deliverable'},[ordered]@{from='DELIVERABLE-PORT-01';to='TKT-PORT-01';type='deliverable-ticket'});$out|ConvertTo-Json -Depth 40|Set-Content (Join-Path $d 'project-story.json') -Encoding utf8
$out=Get-Content (Join-Path $d 'project-story.json') -Raw|ConvertFrom-Json;$out.offer|Add-Member -NotePropertyName id -NotePropertyValue 'OFFER-PORT-01' -Force;$out.graph=@([ordered]@{from='OFFER-PORT-01';to='PAGE-PORT-01';type='offer-page'},[ordered]@{from='PAGE-PORT-01';to='OFFER-PORT-01';type='page-offer'})+$out.graph;$out|ConvertTo-Json -Depth 40|Set-Content (Join-Path $d 'project-story.json') -Encoding utf8
